import requests
# Check data.gov for GSA Schedule 70 SIN data
urls = [
    'https://catalog.data.gov/dataset?tags=gsa+schedule+70',
    'https://catalog.data.gov/api/3/action/package_search?q=gsa+schedule+70',
    'https://catalog.data.gov/api/3/action/package_search?q=special+item+number+gsa',
]
for url in urls:
    try:
        r = requests.get(url, timeout=15)
        print(f'{url} -> {r.status_code}')
        if r.status_code == 200:
            if 'json' in r.headers.get('Content-Type', ''):
                data = r.json()
                print(f'  Results: {data.get("result", {}).get("count", 0)}')
                for item in data.get('result', {}).get('results', [])[:3]:
                    print(f'    {item.get("title", "N/A")}: {item.get("name", "N/A")}')
            else:
                print(f'  HTML length: {len(r.text)}')
    except Exception as e:
        print(f'{url} -> Error: {e}')

import requests
# Try to find GSA SIN reference data
urls = [
    'https://www.gsa.gov/system/files/Schedule_70_SIN_Crosswalk.xlsx',
